SET TIME ZONE 'UTC';
WITH m AS (SELECT generate_series(DATE '2023-01-01',DATE '2025-12-01','1 month')::date mes),x AS (SELECT m.mes,coalesce(sum(v.receita_mercadoria_pre_devolucao) FILTER(WHERE v.elegivel),0) receita FROM m LEFT JOIN pedidos p ON date_trunc('month',p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date=m.mes LEFT JOIN vw_itens_venda v USING(pedido_id) GROUP BY 1) SELECT mes,receita,avg(receita) over(order by mes rows between 2 preceding and current row) media_movel_3m,count(*) over(order by mes rows between 2 preceding and current row) meses_na_janela FROM x ORDER BY mes;
